#include <iostream>
#include <string>

// Minimal generic container demonstrating template syntax
template <typename T>
class ValueHolder {
public:
    explicit ValueHolder(const T& val) : value(val) {}

    const T& get() const { return value; }
    void set(const T& val) { value = val; }

private:
    T value;
};

int main() {
    // Compiler generates ValueHolder<int> specialization
    ValueHolder<int> intHolder(42);
    std::cout << "Int value: " << intHolder.get() << "\n";

    // Compiler generates ValueHolder<std::string> specialization
    ValueHolder<std::string> strHolder("Generic C++");
    std::cout << "String value: " << strHolder.get() << "\n";

    return 0;
}

#include <iostream>
#include <deque>
#include <string>

template <typename T>
class Stack {
public:
    // Return the top element
    T& top() {
        return stack.front();
    }

    const T& top() const {
        return stack.front();
    }

    // Push an element onto the stack
    void push(const T& pushValue) {
        stack.push_front(pushValue);
    }

    // Pop an element from the stack
    void pop() {
        stack.pop_front();
    }

    // Determine whether stack is empty
    bool isEmpty() const {
        return stack.empty();
    }

    // Return size of stack
    size_t size() const {
        return stack.size();
    }

private:
    std::deque<T> stack; // internal storage
};

int main() {
    Stack<double> doubleStack;
    double val = 1.1;
    for (size_t i = 0; i < 3; ++i) {
        doubleStack.push(val);
        std::cout << "Pushed: " << val << "\n";
        val += 1.1;
    }

    std::cout << "Stack size: " << doubleStack.size() << "\n";
    std::cout << "Popping elements: ";
    while (!doubleStack.isEmpty()) {
        std::cout << doubleStack.top() << " ";
        doubleStack.pop();
    }
    std::cout << "\n";

    return 0;
}
